globalThis.__HOSHIN_CONTENT_SCRIPT_READY__ = true;

// Keep extension notices in one responsive stack so they never cover each other.
(() => {
  const stackId = 'paradox-notification-stack';
  const noticeIds = ['channa-download-toast', 'channa-omni-toast', 'channa-farm-slot-banner'];
  const ensureStack = () => {
    const root = document.body || document.documentElement;
    if (!root) return;
    let stack = document.getElementById(stackId);
    if (!stack) {
      stack = document.createElement('div');
      stack.id = stackId;
      stack.setAttribute('aria-live', 'polite');
      stack.style.cssText = 'position:fixed!important;top:max(52px,calc(env(safe-area-inset-top) + 48px))!important;left:50%!important;right:auto!important;bottom:auto!important;transform:translateX(-50%)!important;z-index:2147483646!important;display:flex!important;flex-direction:column!important;align-items:center!important;gap:8px!important;width:max-content!important;max-width:calc(100vw - 24px)!important;pointer-events:none!important;';
      root.appendChild(stack);
    }
    const seen = new Set();
    for (const id of noticeIds) {
      const notice = document.getElementById(id);
      if (!notice || notice === stack) continue;
      const text = (notice.innerText || notice.textContent || '').replace(/\s+/g, ' ').trim().toLowerCase();
      if (text && seen.has(text)) { notice.remove(); continue; }
      if (text) seen.add(text);
      if (stack.contains(notice)) continue;
      for (const [name, value] of Object.entries({position:'relative',top:'auto',right:'auto',bottom:'auto',left:'auto',transform:'none',margin:'0',width:'fit-content',maxWidth:'100%',boxSizing:'border-box',whiteSpace:'normal',overflowWrap:'anywhere',padding:'10px 14px',borderRadius:'12px',background:'rgba(25,24,23,.97)',border:'1px solid rgba(239,75,43,.55)',boxShadow:'0 8px 24px rgba(0,0,0,.36)'})) {
        notice.style.setProperty(name.replace(/[A-Z]/g, c => '-' + c.toLowerCase()), value, 'important');
      }
      stack.appendChild(notice);
    }
    const status = document.getElementById('hoshin-container-status');
    if (status && document.getElementById('channa-top-center-capsule')) status.remove();
  };
  ensureStack();
  const observer = new MutationObserver(ensureStack);
  observer.observe(document.documentElement, {childList:true,subtree:true});
})();
